import "server-only";
import crypto from "node:crypto";
import { KMSClient, GenerateDataKeyCommand, DecryptCommand } from "@aws-sdk/client-kms";
import { env } from "./env";

/* =====================================================================
 * Envelope encryption for PII (email, phone, …)
 *
 *  - With AWS_KMS_KEY_ID set: a 256-bit data key is generated by KMS
 *    (GenerateDataKey). Plaintext key lives only in memory; the KMS-encrypted
 *    copy is stored next to every ciphertext. Format:  k1.<b64 json>
 *  - Without it (local dev): AES-256-GCM with APP_LOCAL_DATA_KEY. Format: l1.<b64 json>
 *
 *  Same structure as the PHP kms_helper (ciphertext / iv / tag / key) so data
 *  can be migrated between stacks.
 * ===================================================================== */

const kms =
  env.aws.kmsKeyId !== ""
    ? new KMSClient({
        region: env.aws.region,
        ...(env.aws.accessKeyId && env.aws.secretAccessKey
          ? { credentials: { accessKeyId: env.aws.accessKeyId, secretAccessKey: env.aws.secretAccessKey } }
          : {}), // otherwise default provider chain (IAM role on EC2/ECS)
      })
    : null;

type DataKey = { plain: Buffer; wrapped: string; createdAt: number };
let currentKey: DataKey | null = null;
const DATA_KEY_TTL_MS = 60 * 60 * 1000; // rotate data key hourly
const unwrapCache = new Map<string, Buffer>(); // wrapped(b64) -> plain key
const UNWRAP_CACHE_MAX = 500;

async function getDataKey(): Promise<DataKey> {
  if (currentKey && Date.now() - currentKey.createdAt < DATA_KEY_TTL_MS) return currentKey;
  if (!kms) throw new Error("KMS not configured");
  const out = await kms.send(new GenerateDataKeyCommand({ KeyId: env.aws.kmsKeyId, KeySpec: "AES_256" }));
  if (!out.Plaintext || !out.CiphertextBlob) throw new Error("KMS GenerateDataKey failed");
  const plain = Buffer.from(out.Plaintext);
  const wrapped = Buffer.from(out.CiphertextBlob).toString("base64");
  unwrapCache.set(wrapped, plain);
  currentKey = { plain, wrapped, createdAt: Date.now() };
  return currentKey;
}

async function unwrapKey(wrapped: string): Promise<Buffer> {
  const hit = unwrapCache.get(wrapped);
  if (hit) return hit;
  if (!kms) throw new Error("KMS not configured");
  const out = await kms.send(new DecryptCommand({ CiphertextBlob: Buffer.from(wrapped, "base64") }));
  if (!out.Plaintext) throw new Error("KMS Decrypt failed");
  const plain = Buffer.from(out.Plaintext);
  if (unwrapCache.size >= UNWRAP_CACHE_MAX) unwrapCache.delete(unwrapCache.keys().next().value as string);
  unwrapCache.set(wrapped, plain);
  return plain;
}

function localKey(): Buffer {
  const hex = env.localDataKey;
  if (!/^[0-9a-f]{64}$/i.test(hex)) throw new Error("APP_LOCAL_DATA_KEY must be 64 hex chars");
  return Buffer.from(hex, "hex");
}

function gcmEncrypt(key: Buffer, plaintext: string, aad: string) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv("aes-256-gcm", key, iv);
  cipher.setAAD(Buffer.from(aad));
  const ct = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
  return { ciphertext: ct.toString("base64"), iv: iv.toString("base64"), tag: cipher.getAuthTag().toString("base64") };
}

function gcmDecrypt(key: Buffer, p: { ciphertext: string; iv: string; tag: string }, aad: string): string {
  const decipher = crypto.createDecipheriv("aes-256-gcm", key, Buffer.from(p.iv, "base64"));
  decipher.setAAD(Buffer.from(aad));
  decipher.setAuthTag(Buffer.from(p.tag, "base64"));
  return Buffer.concat([decipher.update(Buffer.from(p.ciphertext, "base64")), decipher.final()]).toString("utf8");
}

const AAD = "skyo:pii:v1";

export async function encrypt(plaintext: string): Promise<string> {
  if (kms) {
    const dk = await getDataKey();
    const body = { ...gcmEncrypt(dk.plain, plaintext, AAD), key: dk.wrapped };
    return "k1." + Buffer.from(JSON.stringify(body)).toString("base64");
  }
  const body = gcmEncrypt(localKey(), plaintext, AAD);
  return "l1." + Buffer.from(JSON.stringify(body)).toString("base64");
}

export async function decrypt(value: string | null | undefined): Promise<string> {
  if (!value) return "";
  try {
    const [ver, b64] = [value.slice(0, 3), value.slice(3)];
    const body = JSON.parse(Buffer.from(b64, "base64").toString("utf8"));
    if (ver === "k1.") return gcmDecrypt(await unwrapKey(body.key), body, AAD);
    if (ver === "l1.") return gcmDecrypt(localKey(), body, AAD);
    return "";
  } catch (e) {
    console.error("[crypto] decrypt failed:", (e as Error).name);
    return "";
  }
}

export const encryptionMode = (): "aws-kms" | "local-aes" => (kms ? "aws-kms" : "local-aes");

/* ---------------------------------------------------------------------
 * Hashing helpers
 * ------------------------------------------------------------------- */

/** Deterministic keyed hash for exact-match lookups of encrypted columns. */
export function blindIndex(kind: "email" | "phone", value: string): string {
  return crypto.createHmac("sha256", env.hmacSecret).update(`bidx:${kind}:${value}`).digest("hex");
}

/** Keyed hash for OTP codes (bound to challenge id so hashes are not reusable). */
export function hashOtp(challengeId: string, code: string): string {
  return crypto.createHmac("sha256", env.hmacSecret).update(`otp:${challengeId}:${code}`).digest("hex");
}

export function sha256(v: string): string {
  return crypto.createHash("sha256").update(v).digest("hex");
}

export function randomToken(bytes = 32): string {
  return crypto.randomBytes(bytes).toString("base64url");
}

export function randomOtp(): string {
  return crypto.randomInt(0, 1_000_000).toString().padStart(6, "0");
}

export function safeEqualHex(a: string, b: string): boolean {
  const ab = Buffer.from(a, "hex");
  const bb = Buffer.from(b, "hex");
  return ab.length === bb.length && crypto.timingSafeEqual(ab, bb);
}

/** Sortable 26-char public id. */
export function newUid(): string {
  const time = Date.now().toString(36).padStart(10, "0");
  return (time + crypto.randomBytes(10).toString("hex")).slice(0, 26).toUpperCase();
}

/* ---------------------------------------------------------------------
 * Passwords — scrypt (memory hard), N=2^15, r=8, p=1, 64-byte key
 * ------------------------------------------------------------------- */
const SCRYPT = { N: 32768, r: 8, p: 1, keylen: 64, maxmem: 64 * 1024 * 1024 };

export function hashPassword(password: string): Promise<string> {
  const salt = crypto.randomBytes(16);
  return new Promise((resolve, reject) =>
    crypto.scrypt(password, salt, SCRYPT.keylen, { N: SCRYPT.N, r: SCRYPT.r, p: SCRYPT.p, maxmem: SCRYPT.maxmem }, (err, key) =>
      err ? reject(err) : resolve(`scrypt$${SCRYPT.N}$${SCRYPT.r}$${SCRYPT.p}$${salt.toString("base64")}$${key.toString("base64")}`),
    ),
  );
}

export function verifyPassword(password: string, stored: string): Promise<boolean> {
  const parts = stored.split("$");
  if (parts.length !== 6 || parts[0] !== "scrypt") return Promise.resolve(false);
  const [, N, r, p, saltB64, keyB64] = parts;
  const expected = Buffer.from(keyB64, "base64");
  return new Promise((resolve) =>
    crypto.scrypt(
      password,
      Buffer.from(saltB64, "base64"),
      expected.length,
      { N: +N, r: +r, p: +p, maxmem: SCRYPT.maxmem },
      (err, key) => resolve(!err && crypto.timingSafeEqual(key, expected)),
    ),
  );
}

/** A real-looking hash for timing-safe "user not found" paths. */
export const DUMMY_PASSWORD_HASH =
  "scrypt$32768$8$1$AAAAAAAAAAAAAAAAAAAAAA==$" + Buffer.alloc(64).toString("base64");
